package com.hau.question.infrastructure.persistence.adapter;
import com.hau.question.application.port.out.ProcessedEventRepository; import com.hau.question.infrastructure.persistence.entity.ProcessedEventEntity; import com.hau.question.infrastructure.persistence.repository.ProcessedEventJpaRepository; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Component;
@Component public class ProcessedEventPersistenceAdapter implements ProcessedEventRepository {private final ProcessedEventJpaRepository repo;public ProcessedEventPersistenceAdapter(ProcessedEventJpaRepository r){repo=r;}public boolean exists(UUID id){return repo.existsById(id);}public void record(UUID id,String type){var e=new ProcessedEventEntity();e.eventId=id;e.eventType=type;e.processedAt=Instant.now();repo.save(e);}}
